// ServerInterface represents all server handlers.
type ServerInterface interface {
	// BiometricChallenge Request a login challenge (unauthenticated, non-oracular)
	// (POST /auth/biometric/challenge)
	BiometricChallenge(w http.ResponseWriter, r *http.Request)
	// BiometricVerify Verify the signed challenge -> new session (amr=bio)
	// (POST /auth/biometric/verify)
	BiometricVerify(w http.ResponseWriter, r *http.Request)
	// DemoLogin Demo primary login (stand-in for password+2FA). Returns a limited-scope bootstrap token only.
	// (POST /auth/demo-login)
	DemoLogin(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current session and refresh family
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// VerifyPin PIN unlock -> new session (new refresh family)
	// (POST /auth/pin/verify)
	VerifyPin(w http.ResponseWriter, r *http.Request)
	// Refresh Rotate the refresh token and get a new access token (no body; refresh token in Authorization header)
	// (POST /auth/refresh)
	Refresh(w http.ResponseWriter, r *http.Request)
	// GetDashboard Mock balances (access token required; bootstrap token gets 403)
	// (GET /dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request)
	// ListDevices List the caller's own devices
	// (GET /devices)
	ListDevices(w http.ResponseWriter, r *http.Request)
	// RegisterDevice Register this installation as a device; server generates the deviceId and binds the bootstrap token to it
	// (POST /devices)
	RegisterDevice(w http.ResponseWriter, r *http.Request, params RegisterDeviceParams)
	// RevokeDevice Revoke a device (sessions, refresh tokens, biometric keys)
	// (DELETE /devices/{deviceId})
	RevokeDevice(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath, params RevokeDeviceParams)
	// BiometricDisable Disable biometrics for the device (revokes the key and its challenges)
	// (DELETE /devices/{deviceId}/biometric)
	BiometricDisable(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath)
	// BiometricEnroll Step 2 of enrollment - submit public key with proof of possession
	// (POST /devices/{deviceId}/biometric/enroll)
	BiometricEnroll(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath, params BiometricEnrollParams)
	// BiometricEnrollChallenge Step 1 of enrollment - issue an enroll challenge (consumes the PIN step-up token)
	// (POST /devices/{deviceId}/biometric/enroll/challenge)
	BiometricEnrollChallenge(w http.ResponseWriter, r *http.Request, deviceId DeviceIdPath, params BiometricEnrollChallengeParams)
	// Healthz Liveness and fail-closed readiness (unauthenticated, no data)
	// (GET /healthz)
	Healthz(w http.ResponseWriter, r *http.Request)
	// SetPin Set the initial PIN (only when no PIN exists)
	// (POST /pin)
	SetPin(w http.ResponseWriter, r *http.Request, params SetPinParams)
	// ChangePin Change PIN (old PIN required; counts toward lockout)
	// (PUT /pin)
	ChangePin(w http.ResponseWriter, r *http.Request, params ChangePinParams)
	// ResetPin Forgot PIN / hard-lock recovery
	// (POST /pin/reset)
	ResetPin(w http.ResponseWriter, r *http.Request, params ResetPinParams)
	// StepupChallenge Start a step-up for a sensitive action
	// (POST /stepup/challenge)
	StepupChallenge(w http.ResponseWriter, r *http.Request)
	// StepupVerify Prove the step-up (signature or PIN) -> single-use step-up token
	// (POST /stepup/verify)
	StepupVerify(w http.ResponseWriter, r *http.Request)
	// CreateTransaction Demo send (mock). Requires step-up token; server recomputes the tx hash from this body
	// (POST /transactions)
	CreateTransaction(w http.ResponseWriter, r *http.Request, params CreateTransactionParams)
}

