// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.Healthz)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/demo-login", wrapper.DemoLogin)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/devices", wrapper.ListDevices)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/devices", wrapper.RegisterDevice)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/devices/{deviceId}", wrapper.RevokeDevice)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/pin", wrapper.SetPin)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/pin", wrapper.ChangePin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/pin/reset", wrapper.ResetPin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/pin/verify", wrapper.VerifyPin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/biometric/challenge", wrapper.BiometricChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/biometric/verify", wrapper.BiometricVerify)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/refresh", wrapper.Refresh)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/devices/{deviceId}/biometric/enroll/challenge", wrapper.BiometricEnrollChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/devices/{deviceId}/biometric/enroll", wrapper.BiometricEnroll)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/devices/{deviceId}/biometric", wrapper.BiometricDisable)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/stepup/challenge", wrapper.StepupChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/stepup/verify", wrapper.StepupVerify)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/transactions", wrapper.CreateTransaction)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/dashboard", wrapper.GetDashboard)
	})

	return r
}

