// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// BiometricChallenge Request a login challenge (unauthenticated, non-oracular)
	// (POST /auth/biometric/challenge)
	BiometricChallenge(ctx context.Context, request BiometricChallengeRequestObject) (BiometricChallengeResponseObject, error)
	// BiometricVerify Verify the signed challenge -> new session (amr=bio)
	// (POST /auth/biometric/verify)
	BiometricVerify(ctx context.Context, request BiometricVerifyRequestObject) (BiometricVerifyResponseObject, error)
	// DemoLogin Demo primary login (stand-in for password+2FA). Returns a limited-scope bootstrap token only.
	// (POST /auth/demo-login)
	DemoLogin(ctx context.Context, request DemoLoginRequestObject) (DemoLoginResponseObject, error)
	// Logout Revoke the current session and refresh family
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// VerifyPin PIN unlock -> new session (new refresh family)
	// (POST /auth/pin/verify)
	VerifyPin(ctx context.Context, request VerifyPinRequestObject) (VerifyPinResponseObject, error)
	// Refresh Rotate the refresh token and get a new access token (no body; refresh token in Authorization header)
	// (POST /auth/refresh)
	Refresh(ctx context.Context, request RefreshRequestObject) (RefreshResponseObject, error)
	// GetDashboard Mock balances (access token required; bootstrap token gets 403)
	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)
	// ListDevices List the caller's own devices
	// (GET /devices)
	ListDevices(ctx context.Context, request ListDevicesRequestObject) (ListDevicesResponseObject, error)
	// RegisterDevice Register this installation as a device; server generates the deviceId and binds the bootstrap token to it
	// (POST /devices)
	RegisterDevice(ctx context.Context, request RegisterDeviceRequestObject) (RegisterDeviceResponseObject, error)
	// RevokeDevice Revoke a device (sessions, refresh tokens, biometric keys)
	// (DELETE /devices/{deviceId})
	RevokeDevice(ctx context.Context, request RevokeDeviceRequestObject) (RevokeDeviceResponseObject, error)
	// BiometricDisable Disable biometrics for the device (revokes the key and its challenges)
	// (DELETE /devices/{deviceId}/biometric)
	BiometricDisable(ctx context.Context, request BiometricDisableRequestObject) (BiometricDisableResponseObject, error)
	// BiometricEnroll Step 2 of enrollment - submit public key with proof of possession
	// (POST /devices/{deviceId}/biometric/enroll)
	BiometricEnroll(ctx context.Context, request BiometricEnrollRequestObject) (BiometricEnrollResponseObject, error)
	// BiometricEnrollChallenge Step 1 of enrollment - issue an enroll challenge (consumes the PIN step-up token)
	// (POST /devices/{deviceId}/biometric/enroll/challenge)
	BiometricEnrollChallenge(ctx context.Context, request BiometricEnrollChallengeRequestObject) (BiometricEnrollChallengeResponseObject, error)
	// Healthz Liveness and fail-closed readiness (unauthenticated, no data)
	// (GET /healthz)
	Healthz(ctx context.Context, request HealthzRequestObject) (HealthzResponseObject, error)
	// SetPin Set the initial PIN (only when no PIN exists)
	// (POST /pin)
	SetPin(ctx context.Context, request SetPinRequestObject) (SetPinResponseObject, error)
	// ChangePin Change PIN (old PIN required; counts toward lockout)
	// (PUT /pin)
	ChangePin(ctx context.Context, request ChangePinRequestObject) (ChangePinResponseObject, error)
	// ResetPin Forgot PIN / hard-lock recovery
	// (POST /pin/reset)
	ResetPin(ctx context.Context, request ResetPinRequestObject) (ResetPinResponseObject, error)
	// StepupChallenge Start a step-up for a sensitive action
	// (POST /stepup/challenge)
	StepupChallenge(ctx context.Context, request StepupChallengeRequestObject) (StepupChallengeResponseObject, error)
	// StepupVerify Prove the step-up (signature or PIN) -> single-use step-up token
	// (POST /stepup/verify)
	StepupVerify(ctx context.Context, request StepupVerifyRequestObject) (StepupVerifyResponseObject, error)
	// CreateTransaction Demo send (mock). Requires step-up token; server recomputes the tx hash from this body
	// (POST /transactions)
	CreateTransaction(ctx context.Context, request CreateTransactionRequestObject) (CreateTransactionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

